import java.util.Objects;
public class E212 {
    static class Safe {
        String name;
        Safe(String n){ name = n; }
        @Override public boolean equals(Object o){
            if (!(o instanceof Safe s)) return false;  // null-safe
            return Objects.equals(name, s.name);
        }
    }
    static class Buggy {
        String name;
        Buggy(String n){ name = n; }
        @Override public boolean equals(Object o){
            Buggy b = (Buggy) o;          // 未判空：o==null 时 NPE
            return name.equals(b.name);
        }
    }
    public static void main(String[] args) {
        Safe a = new Safe("java");
        System.out.println("Safe equals null: " + a.equals(null));
        System.out.println("Objects.equals(Safe,null): " + Objects.equals(a, null));
        Buggy b = new Buggy("java");
        try {
            System.out.println("Buggy equals null: " + b.equals(null));
        } catch (NullPointerException e) {
            System.out.println("Buggy equals(null) -> NPE");
        }
    }
}
